(function(root){
'use strict';
function safeName(s){if(typeof s!=='string'||!s.trim()||s!==s.trim()||s.length>120||/[<>:"/\\|?*\u0000-\u001f]/.test(s)||/[. ]$/.test(s)||/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])($|\.)/i.test(s)||s==='.'||s==='..')throw Error('Nombre no válido para Windows: '+s);return s;}
function validate(rows,files,types){const approved=rows.filter(r=>r.approved);if(!approved.length)throw Error('Aprueba al menos un documento.');const paths=new Set();for(const r of approved){const f=files.find(f=>f.id===r.fileId);if(!f)throw Error('Falta el original de un documento aprobado.');safeName(r.key);if(!types.includes(r.type))throw Error('Selecciona un tipo del catálogo para cada documento aprobado.');safeName(r.type);if(!Number.isInteger(r.from)||!Number.isInteger(r.to)||r.from<1||r.to<r.from||r.to>f.pages)throw Error('Rango inválido en '+f.name);if(!/^\d{1,6}$/.test(r.seq))throw Error('Usa un consecutivo de 1 a 6 dígitos.');const path=r.key+'/'+r.type+'_'+r.seq+'.pdf';const folded=path.toLocaleLowerCase('es');if(paths.has(folded))throw Error('Destino repetido: '+path);paths.add(folded);}return approved;}
function coverage(rows,files){return files.map(f=>{const rs=rows.filter(r=>r.approved&&r.fileId===f.id);const hits=new Uint16Array(f.pages);for(const r of rs)for(let p=r.from;p<=r.to;p++)if(p>=1&&p<=f.pages)hits[p-1]++;return{archivo:f.name,paginas:f.pages,generadas:rs.length,omitidas:Array.from(hits,(_,i)=>hits[i]===0?i+1:null).filter(Boolean),repetidas:Array.from(hits,(_,i)=>hits[i]>1?i+1:null).filter(Boolean)};});}
function csv(rows){if(!rows.length)return '\ufeff';const headers=Object.keys(rows[0]);const esc=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';return '\ufeff'+[headers,...rows.map(r=>headers.map(h=>r[h]))].map(a=>a.map(esc).join(';')).join('\r\n');}
const api={safeName,validate,coverage,csv};if(typeof module!=='undefined')module.exports=api;root.FoncepCore=api;
})(typeof window!=='undefined'?window:globalThis);
